import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData,headingForCorrection} from './product-title-corrections.mjs';
const rows=[{id:'mlMLB6472086508',titulo:'Perfume Árabe Ameerati Feminino Eau De Parfum 100 Ml Com Nf lipx',listing:'MLB6472086508'},{id:'mlMLB6795714040',titulo:'Lanterna Tática Voxo Militar T9 Zoom Ultra Potente Bateria Longa Duração Recarregável Usb Resistente Água Poeira Defesa Caça Camping',listing:'MLB6795714040'},{id:'mlMLB7482222950',titulo:'Mochila Escolar Reforçada Xiaobang BW-1904D Preto 40L Para Notebook 17 Polegadas',listing:'MLB7482222950'}];
test('triagem42 mantém campos operacionais e recusa acessórios ou anúncios distintos',()=>{
 for(const r of rows){const p={...r,link:'https://www.mercadolivre.com.br/p/MLB12345678?wid='+r.listing,linkAfiliado:'https://meli.la/preservado',preco:'55,55',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}
});
test('Ameerati não autentica marca e origem nem inventa notas e fixação',()=>{const x=correctProductData(rows[0]);assert.match(x.comentario,/não validação de fabricante/);assert.match(x.comentario,/não permite copiar/);assert.match(x.comentario,/não substitui a confirmação/);assert.doesNotMatch(x.pros,/oficial|original|fixação|oud|baunilha|garant/i);});
test('Voxo qualifica potência bateria e proteção sem inventar números',()=>{const x=correctProductData(rows[1]);assert.doesNotMatch(x.titulo,/militar|defesa|ultra potente|longa duração/i);assert.match(x.comentario,/não há informação técnica suficiente/);assert.match(x.comentario,/não indicamos.*defesa/);assert.match(x.comentario,/sem esclarecer inequivocamente/);assert.doesNotMatch(x.pros,/garant|IP\d|\d+\s*(?:horas|watts|metros)/i);});
test('Xiaobang não promete impermeabilidade ou compatibilidade só pela diagonal',()=>{const x=correctProductData(rows[2]);assert.match(x.comentario,/não garante que qualquer notebook/);assert.match(x.comentario,/Não prometemos impermeabilidade/);assert.doesNotMatch(x.pros,/à prova|garant|impermeável|mais durável/i);});
